def _require(condition: bool, message: str) -> None:
    if not condition:
        raise ValueError(message)


def _replace_exact(text: str, old: str, new: str, *, count: int = 1) -> str:
    observed = text.count(old)
    _require(observed == count, f"Expected {count} occurrences, found {observed}: {old[:100]!r}")
    return text.replace(old, new)


def _top_level_span(text: str, name: str) -> tuple[int, int]:
    tree = ast.parse(text)
    matches = [
        node
        for node in tree.body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef))
        and node.name == name
    ]
    _require(len(matches) == 1, f"Expected one top-level definition named {name!r}.")
    node = matches[0]
    _require(node.end_lineno is not None, f"Missing end position for {name!r}.")
    lines = text.splitlines(keepends=True)
    start = sum(len(line) for line in lines[: node.lineno - 1])
    end = sum(len(line) for line in lines[: node.end_lineno])
    while end < len(text) and text[end] == "\n":
        end += 1
    return start, end


def _replace_definition(text: str, name: str, replacement: str) -> str:
    start, end = _top_level_span(text, name)
    normalized = replacement.strip("\n")
    return f"{text[:start]}{normalized}\n\n{text[end:]}"


def _remove_definition(text: str, name: str) -> str:
    start, end = _top_level_span(text, name)
    return f"{text[:start]}{text[end:]}"


def _insert_generated_header(text: str) -> str:
    marker = "from __future__ import annotations\n"
    _require(text.startswith(marker), "Pinned source lost its future import.")
    return text.replace(f"{marker}\n", f"{marker}\n{GENERATED_HEADER}", 1)


