GENERATORS: Mapping[str, Callable[[str], str]] = {
    "evaluate_p2_direct_controller_shard.py": _generate_evaluator,
    "run_p2_direct_controller_matrix.py": _generate_runner,
    "audit_p2_direct_controller_integrity.py": _generate_audit,
    "summarize_p2_direct_controller.py": _generate_summary,
}


def generated_sources() -> dict[Path, str]:
    result: dict[Path, str] = {}
    for source_name, expected_sha256 in SOURCE_SHA256.items():
        source_path = SCRIPT_ROOT / source_name
        raw = source_path.read_bytes()
        observed_sha256 = hashlib.sha256(raw).hexdigest()
        _require(
            observed_sha256 == expected_sha256,
            f"Pinned source SHA256 drifted for {source_name}: {observed_sha256}",
        )
        source = raw.decode("utf-8")
        generated = GENERATORS[source_name](source)
        ast.parse(generated)
        result[SCRIPT_ROOT / OUTPUTS[source_name]] = generated
    return result


def write_generated_sources() -> None:
    for path, source in generated_sources().items():
        path.write_text(source, encoding="utf-8")


def check_generated_sources() -> None:
    mismatches: list[str] = []
    for path, source in generated_sources().items():
        if not path.is_file() or path.read_text(encoding="utf-8") != source:
            mismatches.append(str(path.relative_to(REPOSITORY_ROOT)))
    _require(not mismatches, f"Generated v1.3 sources are stale: {', '.join(mismatches)}")


def main() -> int:
    parser = argparse.ArgumentParser(description="Generate deterministic controller v1.3 forks.")
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--write", action="store_true")
    mode.add_argument("--check", action="store_true")
    args = parser.parse_args()
    if args.write:
        write_generated_sources()
    else:
        check_generated_sources()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
